(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin(x*0.04-t*0.5)*6 + Math.cos(y*0.035+t*0.45)*5;
  const w2y = Math.cos(y*0.038+t*0.55)*6 + Math.sin(x*0.032-t*0.4)*5;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.8],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.2],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*50, 0.11, 2.1, 0.85],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75+4)*40, 0.13, 1.8, 1.05]
  ];
  let aS=0, iS=0, gS=0;
  for(const [sX,sY,f,sp,w] of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS += Math.sin(d*f-t*sp)*w;
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    gS += Math.sin(d*f*1.4-t*sp*0.9+0.8)*w*0.5;
  }
  const act=aS/8, inh=iS/8, glw=gS/8;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    +Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2
    +Math.sin(sx*0.06+t*1.8)*Math.cos(sy*0.05-t*1.3)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    +Math.sin(dist*0.08+ang*2-t*2.5)*0.15;
  const vor=((Math.sin(sx*0.22)*Math.sin(sy*0.22)+Math.sin((sx+sy)*0.16+t)*0.5
    +Math.sin(sx*0.18-t*0.7)*Math.cos(sy*0.2+t*0.9)*0.3)*1.8);
  const vor2=(Math.sin(sx*0.35+t*0.4)*Math.sin(sy*0.3-t*0.6)
    +Math.sin((sx-sy)*0.25+t*1.2)*0.4)*0.6;
  const rd1=Math.tanh((act-inh*0.7+bg*0.3+spiral)*2.2);
  const rd2=Math.tanh((glw*0.6-inh*0.4+vor*0.25+spiral*0.5)*2.0);
  const cross=Math.tanh((rd1*rd2+rd1*0.6+rd2*0.4)*1.8);
  const cell=Math.tanh(vor)*0.2+Math.tanh(vor2)*0.1;
  const detail=Math.sin(sx*0.5+t*3)*Math.sin(sy*0.5-t*2.5)*0.06;
  const blend=cross*0.6+cell*0.25+detail+rd1*0.15;
  const v=blend*0.5+0.5;
  const pal=[
    [5,12,48],[12,45,82],[18,95,115],[25,150,135],
    [120,185,100],[210,195,60],[230,140,55],[220,85,65],
    [180,45,75],[110,25,85],[50,18,70],[5,12,48]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.78+Math.sin(cross*Math.PI)*0.22;
  const edgeR=Math.abs(cross)>0.72?1.2:Math.abs(cross)>0.5?1.08:1.0;
  const glowR=Math.max(0,glw*0.15);
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edgeR+glowR*40)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edgeR+glowR*60)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edgeR+glowR*80)|0)
  ];
}
